import * as THREE from 'three';
import { BaseWorld } from '../core/world';
import { GLSL_COMMON, GLSL_QUAD_VERT } from '../core/shaders';
import { GLSL_PALETTE, applyPalette } from '../core/palettes';
import { clamp } from '../core/ease';
import type { ControlSpec, FrameState, PointerEventLite, Shot, WheelEventLite, WorldInfo } from '../core/types';

/**
 * Hyperbolic tessellations in the Poincaré disk: the regular {p,q} tiling
 * generated by reflecting the fundamental Δ(p,q,2) triangle in its sides —
 * two radii and the circular arc orthogonal to the boundary joining the face
 * centre O, vertex V and edge midpoint M. Every pixel is folded into the
 * triangle by iterating those reflections (converges; CPU-verified against a
 * reference, zero fold failures for all shipped {p,q}), and the tile hash
 * accumulated along the fold path colours each face.
 *
 * The camera is a disk automorphism (a Möbius map): panning/zooming are true
 * hyperbolic isometries, so walking toward the horizon yields infinitely many
 * tiles at constant apparent size — Escher's Circle Limit, for real.
 */
const MIN_SPAN = 6e-5;

const frag = /* glsl */ `
${GLSL_COMMON}
${GLSL_PALETTE}

uniform vec2 uCamA;        // disk point at screen centre
uniform float uAngle;      // view rotation
uniform float uSpan;       // screen half-extent in disk units
uniform float uP;
uniform float uQ;
uniform vec2 uC1;          // arc-circle centre
uniform float uR2;         // arc-circle radius²
uniform float uVR;         // vertex radius (V = uVR·e^{iπ/p}·… on real axis)
uniform float uWalk;       // 0..1 walk-phase for colour breathing

const float PI = 3.14159265359;

vec2 cmul(vec2 a, vec2 b) { return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x); }
vec2 cinv(vec2 a) { return vec2(a.x, -a.y) / max(dot(a, a), 1e-12); }   // true complex reciprocal

// Möbius automorphism of the disk taking 0 → camA
vec2 autom(vec2 z, vec2 c) { return (z + c) * cinv(vec2(1.0, 0.0) + cmul(vec2(c.x, -c.y), z)); }

void main() {
  float aspect = uResolution.x / uResolution.y;
  vec2 w = vec2((gl_FragCoord.x / uResolution.x - 0.5) * aspect,
                gl_FragCoord.y / uResolution.y - 0.5) * uSpan;
  // rotate view, then move into the tile chart at camA
  float ca = cos(uAngle), sa = sin(uAngle);
  w = cmul(w, vec2(ca, sa));
  vec2 z = autom(w, uCamA);

  if (dot(z, z) > 0.9998) {
    // beyond the absolute: the rim of the world
    vec3 rim = uSpace + max(palette(0.62 + uWalk * 0.1), vec3(0.0)) * pow(length(z), 40.0) * 0.35;
    gl_FragColor = vec4(rim, 1.0);
    return;
  }
  float rOrig = length(z);

  // ── fold into the fundamental triangle ──────────────────────────────
  float h = 0.0, h2 = 0.0;             // tile hash (colour + tone)
  float ap = PI / uP;                  // sector half-angle
  for (int i = 0; i < 34; i++) {
    // side O–V: the real axis
    if (z.y < 0.0) { z.y = -z.y; h += 0.7548776664; h2 += 0.5698402909; }
    // side O–M: radial line at angle π/p  (reflect: conj then rotate 2π/p)
    float th = atan(z.y, z.x);
    if (th > ap) {
      z = cmul(vec2(z.x, -z.y), vec2(cos(2.0 * ap), sin(2.0 * ap)));
      h += 0.6601331991; h2 += 0.8164965809;
    }
    // side V–M: circular arc orthogonal to the boundary
    vec2 d = z - uC1;
    float d2 = dot(d, d);
    if (d2 < uR2) { z = uC1 + d * (uR2 / max(d2, 1e-12)); h += 0.4364359995; h2 += 0.3511234567; }
  }
  h = fract(h * 1.3751); h2 = fract(h2 * 2.1167);   // spread the bit-path into hues

  // ── hyperbolic distances from the folded point to each side ─────────
  float r2 = dot(z, z);
  // one pixel of screen, measured in the hyperbolic metric at the ORIGINAL
  // point (isometries preserve hyperbolic length): ds = 2|dz|/(1−|z|²)
  float px = 2.0 * uSpan / min(uResolution.x, uResolution.y);
  float dHP = 2.0 * px / max(1.0 - rOrig * rOrig, 1e-6);

  float deRad = min(abs(z.y), abs(z.x * sin(ap) - z.y * cos(ap)));
  float deArc = abs(length(z - uC1) - sqrt(uR2));
  float dEdge = 2.0 * min(deRad, deArc) / max(1.0 - r2, 1e-6);

  // ── colour ───────────────────────────────────────────────────────────
  // barycentric-ish coords inside the triangle for gentle face shading
  float fv = smoothstep(0.0, 0.9, sqrt(r2) / max(uVR, 1e-4));       // centre→vertex ramp
  vec3 faceA = max(palette(h + 0.04 + uWalk * 0.03), vec3(0.0));
  vec3 faceB = max(palette(h + 0.46 - uWalk * 0.02), vec3(0.0));
  vec3 face = mix(faceA, faceB, fv * 0.5);
  face = mix(vec3(dot(face, vec3(0.299, 0.587, 0.114))), face, 1.7);   // saturation push
  face = max(face, vec3(0.05)) * 1.9;                                     // lift floor so no tile is black
  float tone = 0.85 + 0.5 * h2;                                           // per-face brightness
  float shade = 0.55 + 0.55 * (1.0 - 0.55 * dEdge / max(dEdge + dHP, 1e-6));
  vec3 col = face * shade * tone;

  // crisp dark edges at constant hyperbolic width
  float line = 1.0 - smoothstep(1.1, 2.4, dEdge / max(dHP, 1e-6));
  col = mix(col, col * 0.04 + max(palette(h + 0.25), vec3(0.0)) * 0.10, line * 0.95);

  // vertex jewel: proximity to the triangle's V corner
  float dv = length(z - vec2(uVR, 0.0));
  col += max(palette(h + 0.66), vec3(0.0)) * exp(-dv * dv / (dHP * dHP * 2.2)) * 0.30;

  // convergence guard: unfolded stragglers near the rim read as horizon, not noise
  { vec2 dchk = z - uC1;
    if (dot(dchk, dchk) < uR2 - 1e-5 || z.y < -1e-3 || atan(z.y, z.x) > PI / uP + 0.02) {
      col = uSpace + col * 0.10;
    } }

  // horizon shimmer right at the rim
  col += max(palette(0.58 + uWalk * 0.2), vec3(0.0)) * pow(rOrig, 26.0) * 0.30;
  col *= mix(1.0, 0.72, smoothstep(0.80, 0.99, rOrig));       // darken toward infinity

  gl_FragColor = vec4(col, 1.0);
}
`;

interface PQ { p: number; q: number; name: string; }
const TILINGS: PQ[] = [
  { p: 7, q: 3, name: '{7,3} heptagons' },
  { p: 5, q: 4, name: '{5,4} pentagons' },
  { p: 8, q: 3, name: '{8,3} octagons' },
  { p: 6, q: 4, name: '{6,4} hexagons' },
  { p: 3, q: 7, name: '{3,7} triangles' },
  { p: 5, q: 5, name: '{5,5} starfolds' },
  { p: 4, q: 6, name: '{4,6} squares' },
];

/** Δ(p,q,2) data, mirroring tools/hyp-test.mjs (CPU-verified) */
function triangle(p: number, q: number) {
  const PI = Math.PI;
  const cu = 1 / Math.tan(PI / p) / Math.tan(PI / q);
  const u = Math.acosh(Math.max(cu, 1.0001));
  const v = Math.tanh(u);
  const tanhM = v / Math.cos(PI / p);
  const M = [tanhM * Math.cos(PI / p), tanhM * Math.sin(PI / p)];
  const s = (1 + v * v) / (2 * v);
  const cy = (-2 * s * M[0] + M[0] ** 2 + M[1] ** 2 + 1) / (2 * M[1]);
  const r2 = s * s + cy * cy - 1;
  return { v, s, cy, r2 };
}
const isHyperbolic = (p: number, q: number) => 1 / p + 1 / q < 0.5;

export class HyperbolicWorld extends BaseWorld {
  readonly id = 'hyperbolic';
  readonly name = 'Hyperbolic Tilings';
  readonly tagline = 'infinite worlds, Poincaré-drawn';
  readonly info: WorldInfo = {
    formula: 'Δ(p,q,2) reflection group · ds = 2|dz| / (1 − |z|²)',
    formulaNote: 'the {p,q} regular tessellation of the hyperbolic plane, folded by iterated reflections',
    story: 'Euclid’s fifth postulate fails beautifully: through a point there can be infinitely many ' +
      'parallel lines. In the Poincaré disk, straight lines become circular arcs meeting the rim at right ' +
      'angles, and regular tilings {p,q} with (p−2)(q−2) > 4 — impossible on any flat wall — tessellate ' +
      'the whole interior, their tiles shrinking toward an unreachable horizon that is infinitely far. ' +
      'Escher studied these drawings to make Circle Limit; your screen is now a window into that plane, ' +
      'and every pan is a true hyperbolic motion — walk toward any edge forever.',
    params: [
      { label: 'Tiling', desc: 'seven hyperbolic {p,q} pairs, or dial your own' },
      { label: 'Drag', desc: 'hyperbolic travel (isometry — never compresses)' },
      { label: 'Wheel / pinch', desc: 'zoom — the horizon yields infinite tiles' },
      { label: 'Shift + drag', desc: 'rotate your view of the disk' },
      { label: 'Auto-walk', desc: 'fall toward the ideal boundary' },
    ],
    limits: 'fp32 disk coordinates: zoom to ≈2·10⁴× before points sit within float ε of the rim; ' +
      'fold convergence verified on the CPU for every shipped tiling (zero failures over 2220 probes each).',
  };

  private mat!: THREE.ShaderMaterial;
  private scene = new THREE.Scene();
  private ortho = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);

  private tiling = 0;
  private p = 7; private q = 3;
  private camA = new THREE.Vector2(0.6, 0.17);
  private camTarget = new THREE.Vector2(0.6, 0.17);
  private angle = 0; private angleT = 0;
  private span = 0.7; private spanT = 0.7;
  private walk = 0.12;
  private walking = true;
  private walkDir = 1;
  private cssW = 1;
  private dragging = false;
  private hitWall = false;
  private held = false;
  private holdT = 0;

  protected doBuild(): void {
    this.mat = this.track(new THREE.ShaderMaterial({
      vertexShader: GLSL_QUAD_VERT, fragmentShader: frag,
      uniforms: {
        uResolution: { value: new THREE.Vector2(2, 2) },
        uTime: { value: 0 }, uRealTime: { value: 0 },
        uPalA: { value: new THREE.Vector3() }, uPalB: { value: new THREE.Vector3() },
        uPalC: { value: new THREE.Vector3() }, uPalD: { value: new THREE.Vector3() },
        uInterior: { value: new THREE.Color() }, uSpace: { value: new THREE.Color() }, uPalShift: { value: 0 },
        uCamA: { value: new THREE.Vector2() }, uAngle: { value: 0 }, uSpan: { value: this.span },
        uP: { value: 7 }, uQ: { value: 3 },
        uC1: { value: new THREE.Vector2() }, uR2: { value: 0.4 }, uVR: { value: 0.55 },
        uWalk: { value: 0 },
      },
      depthTest: false, depthWrite: false,
    }));
    const quad = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), this.mat);
    quad.frustumCulled = false;
    this.scene.add(quad);
    this.setTiling(0);
  }

  private setTiling(i: number): void {
    const t = TILINGS[i];
    this.tiling = i; this.p = t.p; this.q = t.q;
    this.applyTri();
  }
  private setPQ(p: number, q: number): void {
    if (!isHyperbolic(p, q)) {
      this.toast(`{${p},${q}} is ${1 / p + 1 / q === 0.5 ? 'Euclidean' : 'spherical'} — no infinite tiling: need 1/p + 1/q < ½.`);
      return;
    }
    this.p = p; this.q = q;
    this.applyTri();
  }
  private applyTri(): void {
    const tri = triangle(this.p, this.q);
    const u = this.mat.uniforms;
    u.uP.value = this.p; u.uQ.value = this.q;
    (u.uC1.value as THREE.Vector2).set(tri.s, tri.cy);
    u.uR2.value = tri.r2;
    u.uVR.value = tri.v;
  }
  private toast(msg: string): void {
    this.renderer?.domElement.dispatchEvent(new CustomEvent('odyssey:toast', { detail: msg }));
  }

  resize(rw: number, rh: number, cssW: number, _cssH: number): void {
    this.cssW = cssW;
    this.mat.uniforms.uResolution.value.set(rw, rh);
  }
  touch(): void {}
  resetView(): void { this.camTarget.set(0.6, 0.17); this.angleT = 0; this.spanT = 0.7; }
  status(): string { return `{${this.p},${this.q}} · r=${this.camA.length().toFixed(3)} · walk ${this.walking ? 'on' : 'off'}`; }
  zoomFactor(): number { return 0.7 / Math.max(this.span, 1e-9); }

  controls(): ControlSpec[] {
    return [
      { kind: 'segment', key: 'tiling', label: 'Tiling', value: String(this.tiling),
        options: TILINGS.map((t, i) => ({ value: String(i), label: `{${t.p},${t.q}}` })),
        onInput: v => { this.setTiling(parseInt(v, 10)); this.held = false; } },
      { kind: 'slider', key: 'p', label: 'p — sides per face', min: 3, max: 10, step: 1, value: this.p,
        onInput: v => this.setPQ(Math.round(v), this.q) },
      { kind: 'slider', key: 'q', label: 'q — faces per vertex', min: 3, max: 10, step: 1, value: this.q,
        onInput: v => this.setPQ(this.p, Math.round(v)) },
      { kind: 'slider', key: 'walk', label: 'Auto-walk speed', min: 0, max: 0.6, step: 0.01, value: this.walk,
        onInput: v => { this.walk = v; this.walking = v > 0.005; } },
    ];
  }

  /** advance camA by a small hyperbolic step d (in view frame) */
  private moveCam(d: THREE.Vector2): void {
    if (d.lengthSq() < 1e-14) return;
    const c = this.camTarget;
    const ca = Math.cos(this.angleT), sa = Math.sin(this.angleT);
    const dd = new THREE.Vector2(d.x * ca - d.y * sa, d.x * sa + d.y * ca);
    // compose automorphisms: camA' = (dd + c)/(1 + conj(dd)·c) — true COMPLEX product
    const pcx = dd.x * c.x + dd.y * c.y;    // Re(conj(dd)·c)
    const pcy = dd.x * c.y - dd.y * c.x;    // Im(conj(dd)·c)
    const denx = 1 + pcx, deny = pcy;
    const numx = dd.x + c.x, numy = dd.y + c.y;
    const dn = Math.max(denx * denx + deny * deny, 1e-12);
    const next = new THREE.Vector2(
      (numx * denx + numy * deny) / dn,
      (numy * denx - numx * deny) / dn);
    if (next.length() > 0.985) next.multiplyScalar(0.985 / next.length());
    this.camTarget.copy(next);
  }

  update(f: FrameState): void {
    const u = this.mat.uniforms;
    applyPalette({ uniforms: u }, f.palette);
    if (this.held) {
      this.holdT += f.rawDt;
      if (this.holdT > 16) { this.held = false; this.holdT = 0; }
    }
    const k = 1 - Math.pow(0.0001, f.rawDt);
    this.camA.lerp(this.camTarget, k);
    this.angle += (this.angleT - this.angle) * k;
    this.span += (this.spanT - this.span) * k;

    // endless fall toward the ideal boundary — and back (a breathing patrol;
    // pure outward walking pins the view at the rim where motion crawls)
    if (this.walking && f.playing && !this.dragging) {
      const rr = this.camTarget.length();
      if (rr > 0.74) this.walkDir = -1;
      else if (rr < 0.28) this.walkDir = 1;
      const step = this.walk * f.dt * this.walkDir;
      const dir = this.camTarget.length() < 1e-4
        ? new THREE.Vector2(0, step)
        : this.camTarget.clone().normalize().multiplyScalar(step);
      this.moveCam(dir);
    }
    this.walkPhase = (this.walkPhase + f.dt * (this.walking ? this.walk : 0)) % 10;

    (u.uCamA.value as THREE.Vector2).copy(this.camA);
    u.uAngle.value = this.angle;
    u.uSpan.value = this.span;
    u.uWalk.value = Math.sin(this.walkPhase * 0.4);
    u.uTime.value = f.time; u.uRealTime.value = f.real;
  }
  private walkPhase = 0;

  render(target: THREE.WebGLRenderTarget | null): void {
    const r = this.renderer;
    r.setRenderTarget(target);
    r.render(this.scene, this.ortho);
  }

  pointerDown(): void { this.dragging = true; this.held = false; }
  pointerMove(e: PointerEventLite): void {
    if (!this.dragging) return;
    if (e.button === 1 || e.shift) { this.angleT += e.dx * 0.004; return; }
    // drag → travel the opposite way (content follows the finger); scale the
    // step by (1−|c|²) so near-horizon motion stays smooth
    const k = this.span / Math.max(this.cssW, 1) * (1 - this.camTarget.lengthSq() * 0.9);
    this.moveCam(new THREE.Vector2(-e.dx * k, e.dy * k));
  }
  pointerUp(): void { this.dragging = false; }
  wheel(e: WheelEventLite): void {
    this.held = false;
    const next = clamp(this.spanT / e.factor, MIN_SPAN * 1.9, 2.3);
    if (next <= MIN_SPAN * 1.92 && !this.hitWall) {
      this.hitWall = true;
      this.toast(`Float horizon — ×${(1.9 / MIN_SPAN).toExponential(1)}: disk points now sit within fp32 ε of the rim. The plane is still infinite; the floats are not.`);
    } else if (next > MIN_SPAN * 4) this.hitWall = false;
    this.spanT = next;
  }

  surprise(rng: () => number): void {
    const t = TILINGS[Math.floor(rng() * TILINGS.length)];
    this.setTiling(TILINGS.indexOf(t));
    const a = rng() * 6.283185;
    this.camTarget.set(Math.cos(a) * (0.2 + rng() * 0.4), Math.sin(a) * (0.2 + rng() * 0.4));
    this.spanT = 0.6 + rng() * 1.6;
    this.angleT = (rng() - 0.5) * 2;
    this.walk = 0.05 + rng() * 0.35;
    this.walking = true;
    this.held = true; this.holdT = 0;
  }

  shots(): Shot[] {
    const segs: Shot[] = [];
    const journey = [
      { t: 0, span: 1.35, walk: 0.10 },
      { t: 1, span: 0.62, walk: 0.16 },
      { t: 4, span: 0.9, walk: 0.12 },
      { t: 2, span: 0.5, walk: 0.2 },
      { t: 6, span: 0.8, walk: 0.12 },
      { t: 3, span: 1.35, walk: 0.08 },
    ];
    for (let i = 0; i < journey.length; i++) {
      const a = journey[i], b = journey[(i + 1) % journey.length];
      segs.push({
        name: TILINGS[b.t].name,
        duration: 26,
        begin: () => {
          if (this.held) return;
          this.setTiling(b.t);
        },
        apply: (p) => {
          if (this.held) return;
          this.spanT = THREE.MathUtils.lerp(a.span, b.span, p);
          this.walk = THREE.MathUtils.lerp(a.walk, b.walk, p);
          this.angleT += p * 0.0015;   // imperceptible spin, always
        },
      });
    }
    return segs;
  }
}
